mapper.sql:
SELECT PPS.PAY_SCHEDULE_NO
  FROM PA_PAY_SCHEDULE PPS
 WHERE TO_CHAR(PPS.PAY_DATE, 'DD-MM-YYYY') = #{payDate, jdbcType=VARCHAR}
   AND PPS.ACTIVITY = 1
   AND PPS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

   AND PPS.SALARY_DISTIN_NO = #{salaryDistinNo, jdbcType=VARCHAR}

sql.if:
AND EXISTS (SELECT 1
              FROM HR_DEPARTMENT B1
             WHERE B1.DEPTNO = PA.DEPTNO
               AND B1.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
             START WITH B1.DEPTNO = #{deptNo, jdbcType=VARCHAR}
           CONNECT BY PRIOR B1.DEPTNO = B1.PARENT_DEPT_NO)

mapper.select:
SELECT HE.PERSON_ID, HE.EMPID, HE.LOCAL_NAME, GET_DEPT_NAME(HE.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPT_NAME, GET_DEPT_NAME(GET_DEPT_NO_BY_LEVEL(HE.DEPTNO, HE.CPNY_ID, '2'), #{lang, jdbcType=VARCHAR}) TEAM_NAME, GET_GLOBAL_NAME(HE.POST_FAMILY, #{lang, jdbcType=VARCHAR}) POST_FAMILY_NAME, GET_GLOBAL_NAME(HE.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) POST_GRADE_NAME, GET_GLOBAL_NAME(HE.POSITION_NO, #{lang, jdbcType=VARCHAR}) POSITION_NAME, GET_GLOBAL_NAME(HE.MAIN_BUSINESS, #{lang, jdbcType=VARCHAR}) MAIN_BUSINESS, GET_GLOBAL_NAME(HE.EMP_OFFICE, #{lang, jdbcType=VARCHAR}) EMP_OFFICE_NAME, GET_GLOBAL_NAME(HE.EMP_TYPE_CODE, #{lang, jdbcType=VARCHAR}) EMP_TYPE_NAME, TO_CHAR(HE.DATE_STARTED, 'DD/MM/YYYY') DATE_STARTED, TO_CHAR(HE.DATE_LEFT, 'DD/MM/YYYY') DATE_LEFT FROM PA_SUMMARY_HAE PST, HR_EMPLOYEE HE,
WHERE HE.PERSON_ID = PST.PERSON_ID AND HE.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND = #{changeType, jdbcType=VARCHAR}
AND = #{changeType, jdbcType=VARCHAR}
ORDER BY HE.EMPID

