mapper.select:
SELECT HRE.EMPID, HRE.LOCAL_NAME, TO_CHAR(TO_DATE(AD.AR_DATE_STR, 'YYYY/MM/DD'), 'DD/MM/YYYY') AR_DATE_STR, TO_CHAR(AD.FROM_TIME, 'DD/MM/YYYY HH24:MI') FROM_TIME, TO_CHAR(AD.TO_TIME, 'DD/MM/YYYY HH24:MI') TO_TIME, GET_GLOBAL_NAME(AD.SHIFT_NO, #{lang, jdbcType=VARCHAR}) SHIFT_NAME, GET_GLOBAL_NAME(AD.ITEM_NO, #{lang, jdbcType=VARCHAR}) ITEM_NAME, AD.QUANTITY FROM AR_DETAIL_HAE AD, HR_EMPLOYEE HRE WHERE AD.PERSON_ID = HRE.PERSON_ID AND AD.ACTIVITY = 1 AND AD.ITEM_NO IN (90000295, 90000296, 90000297, 90000298, 90000299, 90000300, 90000301) AND AD.PERSON_ID = #{personId, jdbcType=VARCHAR}
AND AD.AR_DATE_STR BETWEEN #{arStartDate, jdbcType=VARCHAR} AND #{arEndDate, jdbcType=VARCHAR}
ORDER BY AD.AR_DATE_STR, AD.ITEM_NO
